class UnionFind:

	def __init__(self, n, m):
		self.data = [i for i in range(n + m)]
		self.size = [0] * (m + n)

	def union(self, u, v):
		up = self.find(u)
		vp = self.find(v)
		if up == vp:
			return
		if self.size[up] <= self.size[vp]:
			self.data[up] = vp
			self.size[vp] += self.size[up]
		else:
			self.data[vp] = up
			self.size[up] += self.size[vp]

	def find(self, v):
		if v != self.data[v]:
			self.data[v] = self.find(self.data[v])
		return self.data[v]

