def findMaxSubsequence(seq):
	length = len(seq)
	seqLength = [[0 for i in range(length)] for j in range(length)]
	for i in range(length):
		seqLength[i][i] = 1
	for cols in range(2, length + 1):
		for i in range(0, length - cols + 1):
			j = i + cols - 1
			if seq[i] == seq[j]:
				if cols == 2:
					seqLength[i][j] = 2
				else:
					seqLength[i][j] = seqLength[i + 1][j - 1] + 2
			else:
				seqLength[i][j] = max(seqLength[i + 1][j], seqLength[i][j - 1])
	return seqLength
