class Solution:

	def isUgly(self, num):
		if num < 1:
			return False
		while num % 2 == 0:
			num = num / 2
		while num % 3 == 0:
			num = num / 3
		while num % 5 == 0:
			num = num / 5
		if num == 1:
			return True
		else:
			return False

def pack_bagpack(scores, weights, capacity):
	load = [0] * (capacity + 1)
	for (score, weight) in zip(scores, weights):
		load = [max(l, weight <= w and load[w - weight] + score) for (w, l) in enumerate(load)]
	return load[-1]

